package com.opensocket.aievent.core.iam.persistence.repository;
import static com.opensocket.aievent.core.iam.persistence.repository.RowValues.*;import com.opensocket.aievent.core.iam.authentication.application.port.out.ReauthenticationGrantRepository;import com.opensocket.aievent.core.iam.authentication.domain.ReauthenticationGrant;import com.opensocket.aievent.core.iam.persistence.dao.IamAuthenticationDao;import com.opensocket.aievent.core.iam.persistence.exception.IamOptimisticLockException;import com.opensocket.aievent.core.iam.persistence.tenant.IamTenantContextHolder;import com.opensocket.aievent.database.persistence.spi.DatabaseRepositoryAdapter;import java.util.*;
@DatabaseRepositoryAdapter public class MybatisReauthenticationGrantRepository implements ReauthenticationGrantRepository{private final IamAuthenticationDao dao;public MybatisReauthenticationGrantRepository(IamAuthenticationDao dao){this.dao=dao;}public Optional<ReauthenticationGrant>find(String id){Map<String,Object>r=dao.findRootReauthenticationGrant(id);if(r==null&&IamTenantContextHolder.current().isPresent())r=dao.findTenantReauthenticationGrant(id);return Optional.ofNullable(r).map(this::domain);}public ReauthenticationGrant save(ReauthenticationGrant g,long expected){Optional<String>tenant=IamTenantContextHolder.current().map(c->c.tenantId());Map<String,Object>r=row(g);int n;if(tenant.isPresent()){r.put("tenantId",tenant.get());n=expected==0?dao.insertTenantReauthenticationGrant(r):dao.updateTenantReauthenticationGrant(r,expected);}else n=expected==0?dao.insertRootReauthenticationGrant(r):dao.updateRootReauthenticationGrant(r,expected);if(n!=1)throw new IamOptimisticLockException("ReauthenticationGrant",g.grantId(),expected);return g;}private ReauthenticationGrant domain(Map<String,Object>r){return new ReauthenticationGrant(string(r,"grantId"),string(r,"sessionId"),string(r,"subjectId"),new LinkedHashSet<>(split(string(r,"purposesCsv"))),instant(r,"issuedAt"),instant(r,"expiresAt"),bool(r,"consumed"),longValue(r,"version"));}private Map<String,Object>row(ReauthenticationGrant g){Map<String,Object>r=new HashMap<>();r.put("grantId",g.grantId());r.put("sessionId",g.sessionId());r.put("subjectId",g.subjectId());r.put("purposesCsv",String.join("",g.purposes()));r.put("issuedAt",g.issuedAt());r.put("expiresAt",g.expiresAt());r.put("consumed",g.consumed());r.put("version",g.version());return r;}private List<String>split(String v){return v==null||v.isEmpty()?List.of():Arrays.asList(v.split("",-1));}}
